def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            cellset = set(cells)
            if r1 - r0 >= 2 and c1 - c0 >= 2:
                border = all((r0, x) in cellset and (r1, x) in cellset for x in range(c0, c1 + 1))
                border &= all((y, c0) in cellset and (y, c1) in cellset for y in range(r0, r1 + 1))
                if border:
                    for y in range(r0 + 1, r1):
                        for x in range(c0 + 1, c1):
                            out[y][x] = 2
    return out
